+export function clearNonTeamSavedCandidates(): void {
+  if (typeof window === 'undefined') return;
+  try {
+    const teamEmails = new Set(TEAM_CANDIDATES.map(m => m.primary_email?.toLowerCase().trim()));
+    const teamIds = new Set(TEAM_CANDIDATES.map(m => m.id));
+    const existing = getSavedHRCandidates();
+    const updated = existing.filter(c => {
+      const email = c.primary_email?.toLowerCase().trim();
+      return teamIds.has(c.id) || (email && teamEmails.has(email));
+    });
+    localStorage.setItem(HR_STORAGE_KEY, JSON.stringify(updated));
+    window.dispatchEvent(new CustomEvent('cci_hr_candidates_changed', { detail: { purged: true } }));
+  } catch (e) {
+    console.error('Failed to clear non-team candidates from localStorage', e);
   }
 }

